import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

// Reads kinds/*/dials.json and writes src/core/knob-values.ts. Run it with `pnpm gen:knobs`.
const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

export const HEADER = [
  "// Generated by scripts/gen-knob-values.mjs from kinds/*/dials.json.",
  "// Do not edit this file. Change a dials.json file, then run `pnpm gen:knobs`.",
].join("\n");

/** Reads every kinds/<kind>/dials.json under `root`, in kind-name order, into one flat list of entries. */
export function readDials(root = ROOT) {
  const dir = path.join(root, "kinds");
  const kinds = readdirSync(dir, { withFileTypes: true }).filter((d) => d.isDirectory()).map((d) => d.name).sort();
  const entries = [];
  for (const kind of kinds) {
    let text;
    try {
      text = readFileSync(path.join(dir, kind, "dials.json"), "utf8");
    } catch (e) {
      if (e.code === "ENOENT") continue;
      throw e;
    }
    entries.push(...JSON.parse(text));
  }
  return entries;
}

/** A knob value with float noise taken off: 12 significant digits (0.16000000000000014 becomes 0.16). */
export function clean(value) {
  if (typeof value === "number") return Number(value.toPrecision(12));
  return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, clean(v)]));
}

/** Pure: turns the flat dials list into the text of src/core/knob-values.ts. Throws if a knob lacks exactly one base entry. */
export function render(dials) {
  const byKnob = new Map();
  for (const d of dials) {
    if (!byKnob.has(d.knob)) byKnob.set(d.knob, []);
    byKnob.get(d.knob).push(d);
  }
  const values = {};
  for (const [knob, list] of [...byKnob].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
    const bases = list.filter((d) => d.base === true);
    if (bases.length !== 1) throw new Error(`${knob}: needs exactly one "base": true entry, found ${bases.length}`);
    const base = bases[0];
    values[knob] = {
      base: { value: clean(base.value), bar: base.bar },
      bars: list.map((d) => ({ bar: d.bar, value: clean(d.value) })),
    };
  }
  return [
    HEADER,
    "",
    "export interface KnobSpring { visualDuration: number; bounce: number }",
    "export interface KnobValue { value: number | KnobSpring; bar: string }",
    "export interface KnobBaseInfo { base: KnobValue; bars: KnobValue[] }",
    "",
    "/** Base value and every bar's value, by \"kind.field\". */",
    `export const KNOB_VALUES: Record<string, KnobBaseInfo> = ${JSON.stringify(values, null, 2)};`,
    "",
  ].join("\n");
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const out = path.join(ROOT, "src/core/knob-values.ts");
  writeFileSync(out, render(readDials()));
  console.log(`Wrote ${path.relative(ROOT, out)}`);
}
